// Naive loop: every CUDA call here is on the legacy default stream.
for (int i = 0; i < nBatches; ++i) {
    decode_and_normalize(h_in, i);  // CPU work: 20 ms

    // cudaMemcpy blocks the host until the copy is done
    cudaMemcpy(d_in, h_in, inBytes, cudaMemcpyHostToDevice);    // 16 ms

    infer<<<grid, block>>>(d_in, d_out);                        // 24 ms

    // same stream, so this copy waits for the kernel to finish
    cudaMemcpy(h_out, d_out, outBytes, cudaMemcpyDeviceToHost); //  1 ms
}

// Allocate page-locked host memory for anything you will stream.
float *h_in, *h_out;
cudaMallocHost(&h_in,  inBytes);   // page-locked, DMA-able
cudaMallocHost(&h_out, outBytes);

// Or page-lock a buffer you did not allocate (e.g. from a decoder library):
// cudaHostRegister(thirdPartyPtr, inBytes, cudaHostRegisterDefault);

cudaMemcpyAsync(d_in, h_in, inBytes, cudaMemcpyHostToDevice, stream);
// ... host is free here ...

cudaFreeHost(h_in);
cudaFreeHost(h_out);
// cudaHostUnregister(thirdPartyPtr);

cudaStream_t s1, s2;
cudaStreamCreate(&s1);          // blocking stream
cudaStreamCreate(&s2);          // blocking stream

kernel1<<<grid, block, 0, s1>>>(...);
kernel2<<<grid, block>>>(...);          // legacy default stream
kernel3<<<grid, block, 0, s2>>>(...);
cudaDeviceSynchronize();

// kernel2 waits for kernel1, and kernel3 waits for kernel2.
// Two fixes:
//   cudaStreamCreateWithFlags(&s1, cudaStreamNonBlocking);
//   or compile with nvcc --default-stream per-thread
//   (or define CUDA_API_PER_THREAD_DEFAULT_STREAM)

// Order across streams with no host stall.
cudaEvent_t ready;
cudaEventCreate(&ready);

infer<<<grid, block, 0, compute>>>(d_in, d_out);
cudaEventRecord(ready, compute);              // marker after the kernel

cudaStreamWaitEvent(copyBack, ready, 0);      // GPU-side dependency
cudaMemcpyAsync(h_out, d_out, outBytes,
                cudaMemcpyDeviceToHost, copyBack);

// Timing, measured on the device:
cudaEvent_t t0, t1; float ms;
cudaEventCreate(&t0); cudaEventCreate(&t1);
cudaEventRecord(t0, compute);
infer<<<grid, block, 0, compute>>>(d_in, d_out);
cudaEventRecord(t1, compute);
cudaStreamSynchronize(compute);               // only now does the host wait
cudaEventElapsedTime(&ms, t0, t1);

const int n = 4;
cudaStream_t stream[n];
for (int i = 0; i < n; ++i)
    cudaStreamCreateWithFlags(&stream[i], cudaStreamNonBlocking);

for (int i = 0; i < n; ++i) {
    size_t off     = i * chunkElems;
    size_t outOff  = i * outChunkElems;
    cudaMemcpyAsync(d_in + off, h_in + off, chunkBytes,
                    cudaMemcpyHostToDevice, stream[i]);
    infer<<<blocks, threads, 0, stream[i]>>>(d_in + off, d_out + outOff);
    cudaMemcpyAsync(h_out + outOff, d_out + outOff, outChunkBytes,
                    cudaMemcpyDeviceToHost, stream[i]);
}

// Issue all independent work first, synchronize as late as possible.
for (int i = 0; i < n; ++i) cudaStreamSynchronize(stream[i]);

bool graphCreated = false;
cudaGraph_t graph;
cudaGraphExec_t instance;

for (int istep = 0; istep < NSTEP; ++istep) {
    if (!graphCreated) {
        cudaStreamBeginCapture(stream, cudaStreamCaptureModeGlobal);
        for (int k = 0; k < NKERNEL; ++k)
            shortKernel<<<blocks, threads, 0, stream>>>(out_d, in_d);
        cudaStreamEndCapture(stream, &graph);
        cudaGraphInstantiate(&instance, graph, NULL, NULL, 0);
        graphCreated = true;        // ~400 us, paid once
    }
    cudaGraphLaunch(instance, stream);
    cudaStreamSynchronize(stream);
}

// Two pinned staging buffers, one compute stream, one copy stream.
for (int i = 0; i < nChunks; ++i) {
    int b = i & 1;

    // chunk i-2 was the last user of buffer b; wait only for that event
    if (i >= 2) cudaEventSynchronize(done[b]);

    tokenize(h_stage[b], i);                 // host work, overlaps the GPU

    cudaMemcpyAsync(d_in[b], h_stage[b], bytes,
                    cudaMemcpyHostToDevice, copy);
    cudaEventRecord(ready[b], copy);

    cudaStreamWaitEvent(compute, ready[b], 0);
    step<<<grid, block, 0, compute>>>(d_in[b], d_out[b]);
    cudaEventRecord(done[b], compute);       // buffer b free after this
}
cudaStreamSynchronize(compute);
